/* @lc app=leetcode id=1691 lang=kotlin */
class Solution { fun maxHeight(cuboids: Array<IntArray>): Int = cuboids.map { it.sortedArray() }.sortedWith(compareBy({ it[0] }, { it[1] }, { it[2] })).let { sorted -> IntArray(sorted.size).apply { sorted.indices.forEach { i -> this[i] = sorted[i][2] + ((0 until i).filter { j -> sorted[j][0] <= sorted[i][0] && sorted[j][1] <= sorted[i][1] && sorted[j][2] <= sorted[i][2] }.maxOfOrNull { this[it] } ?: 0) } }.maxOrNull()!! } }